/**
 * NIST NICE coverage report + off-catalog guard.
 *
 * Scans every `nice: [...]` array across src/campaigns/, diffs the claimed
 * codes against scripts/nice-catalog.json (the checked-in valid-code set,
 * regenerated by scripts/gen-nice-catalog.mjs from the reviewer skill), and:
 *   - prints a per-campaign coverage table + product totals,
 *   - lists any off-catalog codes with their file:line,
 *   - exits 1 if any off-catalog code is claimed (this would have caught the
 *     K0108 code that shipped in the signal-hunter sandbox).
 *
 * Run from the repo root:
 *   node scripts/nice-coverage.mjs
 *
 * The same off-catalog assertion runs in CI via
 * test/campaigns/nice-coverage.test.ts.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, relative } from 'node:path';

const scriptsDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(scriptsDir, '..');
const campaignsDir = join(repoRoot, 'src', 'campaigns');

const catalog = JSON.parse(readFileSync(join(scriptsDir, 'nice-catalog.json'), 'utf8'));
const validCodes = new Set(catalog.codes);

/** Recursively list every .ts file under a directory. */
function walkTs(dir) {
  const out = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      out.push(...walkTs(full));
    } else if (entry.endsWith('.ts')) {
      out.push(full);
    }
  }
  return out;
}

const NICE_ARRAY = /nice:\s*\[([^\]]*)\]/g;
const CODE = /['"]([A-Z]\d{4})['"]/g;

/**
 * Extract every claimed NICE code occurrence from campaign source.
 * @returns {{ code: string, campaign: string, file: string, line: number }[]}
 */
function extractClaims() {
  const claims = [];
  for (const file of walkTs(campaignsDir)) {
    const rel = relative(repoRoot, file).replace(/\\/g, '/');
    const campaign = rel.split('/')[2] ?? '(root)';
    const text = readFileSync(file, 'utf8');
    let arrMatch;
    while ((arrMatch = NICE_ARRAY.exec(text)) !== null) {
      const line = text.slice(0, arrMatch.index).split('\n').length;
      let codeMatch;
      CODE.lastIndex = 0;
      while ((codeMatch = CODE.exec(arrMatch[1])) !== null) {
        claims.push({ code: codeMatch[1], campaign, file: rel, line });
      }
    }
  }
  return claims;
}

const claims = extractClaims();

// Per-campaign coverage
const byCampaign = new Map();
for (const { code, campaign } of claims) {
  if (!byCampaign.has(campaign)) byCampaign.set(campaign, new Set());
  byCampaign.get(campaign).add(code);
}

const distinctProductCodes = new Set(claims.map((c) => c.code));
const offCatalog = claims.filter((c) => !validCodes.has(c.code));

console.log('NIST NICE coverage report');
console.log('='.repeat(60));
console.log(`Catalog: ${catalog.count} valid codes (scripts/nice-catalog.json)\n`);

const campaignRows = [...byCampaign.entries()].sort((a, b) => a[0].localeCompare(b[0]));
console.log('Campaign'.padEnd(20), 'Distinct codes');
console.log('-'.repeat(40));
for (const [campaign, codes] of campaignRows) {
  console.log(campaign.padEnd(20), codes.size);
}
console.log('-'.repeat(40));

const validClaimed = [...distinctProductCodes].filter((c) => validCodes.has(c));
const pct = ((validClaimed.length / catalog.count) * 100).toFixed(1);
console.log(`Product distinct in-catalog codes: ${validClaimed.length} / ${catalog.count} (${pct}%)`);
console.log(`Total code occurrences claimed:     ${claims.length}\n`);

if (offCatalog.length > 0) {
  console.error(`OFF-CATALOG CODES (${offCatalog.length}) — not in scripts/nice-catalog.json:`);
  for (const { code, file, line } of offCatalog) {
    console.error(`  ${code}  ${file}:${line}`);
  }
  console.error('\nFix: use an in-catalog code, or add the code to the reviewer');
  console.error('reference files and rerun scripts/gen-nice-catalog.mjs.');
  process.exit(1);
}

console.log('All claimed codes are in-catalog. ✓');
